{"path": "outputs/t07_query.sparql", "content": "PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?item ?itemLabel ?coordinates WHERE {
  ?item wdt:P625 ?coordinates .
  ?item wdt:P17 wd:Q29 .
  ?item wdt:P131 wd:Q11959 .
  ?item rdfs:label ?itemLabel .
  FILTER(lang(?itemLabel) = "en") .
  VALUES ?poi_type { wd:Q33506 wd:Q7657 wd:Q121615 wd:Q39114 wd:Q483501 }
  ?item wdt:P31 ?poi_type .
}
LIMIT 100"}
